//! Raw bindings to the Dart VM embedding API: `dart_api.h` and
//! `dart_native_api.h`, plus `dart_tools_api.h` behind the `tools` feature.
//!
//! These are the host-side headers -- the ones that initialize and run a VM --
//! not `dart_api_dl.h`, which is the function-pointer table a library loaded
//! *into* someone else's VM uses and cannot start one. Nothing here is safe to
//! call without reading the header comment it was generated from; `fl-dart-vm`
//! is the layer that makes them safe.
//!
//! The bindings are generated by `cargo xtask bindgen` from the headers in
//! `third_party/dart-prebuilt/<version>/include` and checked in. They are
//! generated once for every target this crate supports, which is sound because
//! all of them are LP64 Linux: the assertion below is what stops that
//! assumption from quietly extending to a target it does not hold on.

#![no_std]
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::all)]
// The headers' doc comments use `[identifier]` for emphasis and `List<dynamic>`
// style generics, which rustdoc reads as broken intra-doc links and unclosed
// HTML tags. The comments are upstream's text, carried verbatim by bindgen;
// silencing the lints here is what keeps a regenerate from having to edit them.
#![allow(
    rustdoc::broken_intra_doc_links,
    rustdoc::bare_urls,
    rustdoc::invalid_html_tags
)]

#[cfg(not(all(target_os = "linux", target_pointer_width = "64")))]
compile_error!(
    "fl-dart-sys's checked-in bindings are generated for 64-bit Linux; \
     regenerate them for this target with `cargo xtask bindgen` first"
);

mod api {
    include!("bindings/dart_api.rs");
}
pub use api::*;

#[cfg(feature = "tools")]
mod tools {
    use super::api::*;
    include!("bindings/dart_tools_api.rs");
}
#[cfg(feature = "tools")]
pub use tools::*;

/// dart:io's embedder support, through fl-engine's C shim
/// (`tools/dart-prebuilt/fl_dart/fl_dart_io.h`). Bound by hand: three
/// functions of our own, not the SDK's, compiled into every artifact.
mod io {
    use super::api::Dart_Handle;
    extern "C" {
        /// Process-wide, once, before `Dart_Initialize`: starts dart:io's
        /// event handler thread, which is what makes `Timer` work.
        pub fn fl_dart_io_bootstrap();
        /// Process-wide, once, after `Dart_Cleanup`.
        pub fn fl_dart_io_cleanup();
        /// Per isolate, with a current isolate and open scope, after loading:
        /// dart:io's natives and `_setupHooks`. `script_uri` may be null.
        pub fn fl_dart_io_setup_isolate(
            script_uri: *const ::core::ffi::c_char,
            disable_exit: bool,
        ) -> Dart_Handle;
    }
}
pub use io::*;

/// The standalone ELF snapshot loader (`runtime/bin/elf_loader.*`), bundled
/// into the AOT archive by the artifact pipeline. `dart compile aot-snapshot`
/// output must be loaded through this, not dlopen: the ELF's instructions
/// reference a BSS the loader mmaps and wires up, which a plain dlopen leaves
/// unset (the file carries no `_kDartSnapshotBss` symbol), so the first native
/// call crashes. `Dart_LoadELF*` returns the data and text buffers to hand to
/// `Dart_CreateIsolateGroup`, and a handle to unload.
mod elf {
    use core::ffi::{c_char, c_int};

    /// Opaque handle from `Dart_LoadELF*` (elf_loader.h: an empty struct the
    /// loader owns). Not produced by bindgen, since elf_loader.h is not one of
    /// the bound headers.
    #[repr(C)]
    pub struct Dart_LoadedElf {
        _private: [u8; 0],
    }

    extern "C" {
        pub fn Dart_LoadELF(
            filename: *const c_char,
            file_offset: u64,
            error: *mut *const c_char,
            snapshot_data: *mut *const u8,
            snapshot_text: *mut *const u8,
        ) -> *mut Dart_LoadedElf;
        pub fn Dart_LoadELF_Fd(
            fd: c_int,
            file_offset: u64,
            error: *mut *const c_char,
            snapshot_data: *mut *const u8,
            snapshot_text: *mut *const u8,
        ) -> *mut Dart_LoadedElf;
        pub fn Dart_LoadELF_Memory(
            snapshot: *const u8,
            snapshot_size: u64,
            error: *mut *const c_char,
            snapshot_data: *mut *const u8,
            snapshot_text: *mut *const u8,
        ) -> *mut Dart_LoadedElf;
        pub fn Dart_UnloadELF(loaded: *mut Dart_LoadedElf);
    }
}
pub use elf::*;

/// `ILLEGAL_PORT` is a cast in a macro, which bindgen does not translate.
pub const ILLEGAL_PORT: Dart_Port = 0;

/// The Dart SDK these bindings were generated from. The build script refuses
/// an artifact directory whose `VERSION` says otherwise.
pub const DART_SDK_VERSION: &str = "3.13.7";
/// The `dart-lang/sdk` commit of [`DART_SDK_VERSION`]: the `dart_revision`
/// pinned by the tracked Flutter release's engine `DEPS`.
pub const DART_SDK_REVISION: &str = "416e33b0ffaef062a60ec966bb8c82ed2b83f128";

/// The kernel binary format the linked VM reads (`kSupportedKernelFormatVersion`
/// in `runtime/vm/kernel_binary.h`). A dill's header carries the version it was
/// written in.
pub const DART_KERNEL_FORMAT_VERSION: u32 = 138;

/// The snapshot version hash of the linked VM (`make_version.py`'s
/// `MakeSnapshotHashString`, a digest of the VM sources that define the
/// snapshot format). Every AOT snapshot the pinned `gen_snapshot` writes
/// carries it in its header, and the VM accepts no other. Taken from a snapshot
/// the pinned SDK produced; the artifact pipeline records the same value in
/// `VERSION` as `snapshot_hash`, and the build script checks the two agree.
pub const DART_SNAPSHOT_HASH: &str = "0451907c2eaa8467e848c0067bfe8ed4";
